29	INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-11-06-pipel-REF-00468-MOB', 'REF-00468', 'MOB', '495 wheeled mobility device users (manual wheelchair, conventional powered wheelchair and scooter users) measured in a laboratory mock-up hallway; recruited in Buffalo and suburbs (351), Pittsburgh (100) and Ithaca (44); powered wheelchair users deliberately oversampled', 495, 'EXACT', 'EXACT on the population served (people who use wheelchairs and scooters). Two limits are written so the grade is not read as representativeness: the report says the sample is not proportional to national estimates of device type (powered chairs oversampled), and the turning tasks were done in a built mock-up, so a person using a wheelchair in a real corridor with a companion or a door swing is outside it. Scooter users are in the sample and are a different device class from wheelchairs; the report separates them in its tables.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', 'REF-00468', NULL);
