39	INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (96, 'REF-00468', '360-degree turn', 'EN', 'Section 3.3.13, report p. 61 (PDF p. 65)', 'Less than 50% of our manual and powered wheelchair users completed a 360-degree turn within the United States standard turning diameter (Figure 3-12).', NULL, '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
