46	-- search_executions: 3 insert(s), 0 update(s)
47	INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (201, NULL, 5, NULL, 'EN', 1, 'co1', 'intrinsic', 'disabled people''s organisation guidance wheelchair users doorway clear width turning space lived experience participatory design', NULL, 'web', 'scoping', NULL, 15, 15, 0, 'none', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:31', 'No Co-1 source. Fifteen results: UK housing-association and local-authority wheelchair housing design guides (HousingLIN, Camden, Southwark), a Scottish government consultation, Massachusetts 521 CMR 6, a Texas TAS page, a South African SANS 10400 page, an ADA figures page and a Wiley excerpt. They state 1500 mm turning space, 840 to 900 mm door clear opening and 1200 mm hallways, all from code or planning-guidance bodies, none from a disabled persons organisation. R14: a WELL-FORMED query for the question asked; the long natural-language shape returned code pages, so the zero Co-1 yield is a wrong-index and a query-shape result together, not proof of absence. A targeted DPO search (Disability Rights UK, Scope, Centre for Accessible Environments) is not done by this batch and stays open. Results listed in the transcript only (WebSearch leaves no payload); the I5 ledger holds the query.', 0, 'Stated in the session transcript before the search ran: 5-10 results, mostly code-body or consultancy pages; no result genuinely co-produced by disabled people with a measured dimension; at best a few disability-organisation guides (grey, tier 3).', 'planned', NULL, NULL, '2026-11-06 04:31', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL);
48	INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (202, NULL, 5, NULL, 'EN', 2, 'sr_meta', 'intrinsic', 'systematic review wheelchair manoeuvring space requirements doorway width turning space anthropometry', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'partial', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:31', 'No systematic review of manoeuvring space. Ten results: the Steinfeld 2010 review (informahealthcare, DOI 10.1080/10400430903520280, already candidate 151), a Stanford RESNA 2010 worksheet, five pages of the Anthropometry of Wheeled Mobility Project Final Report transcribed on corada.com, ISO 7176-5 (a measurement standard), a CORE PDF (403 on retrieval) and a 2019 International Journal of Occupational Safety and Ergonomics paper on wheelchair-user anthropometry (a systematic review of body and device size, not of space requirements). The surprise is the report: a primary measurement study of 495 wheeled mobility users, found through its transcription, and followed at the next search. The prior (nothing new) was wrong. || CORRECTED 2026-11-06: The journal of the 2019 paper (DOI 10.1080/10803548.2019.1567974) is not stated in the search result; the name given above was inferred from the DOI prefix and is withdrawn.', 0, 'Stated in the session transcript before the search ran: 0-2 reviews, probably the Steinfeld 2010 and Koontz 2010 papers already staged; nothing new expected.', 'planned', NULL, NULL, '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL);
49	INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (203, NULL, 5, NULL, 'EN', NULL, NULL, NULL, '"Anthropometry of Wheeled Mobility Project" Final Report IDeA Center Access Board pdf || retrieved https://idea.ap.buffalo.edu/wp-content/uploads/sites/110/2020/01/AnthropometryofWheeledMobilityProject_FinalReport.pdf', NULL, 'web', 'scoping', NULL, 10, 10, 1, 'saturated', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:32', 'Lookup of a source surfaced by exec 202. The first result is the PDF on idea.ap.buffalo.edu; the others are corada.com transcriptions of its sections, an Access Board page on wheelchair seat height, and a humancentereddesign.org library entry. Retrieved 2026-11-06 (HTTP 200, 14,986,049 bytes, 173 pages, sha256 e664fb2f8174f4f8) and admitted as REF-00468, the stash id that already held this title (the stash row carries an unrelated Husbanken URL: the GAP-008 shuffled-field defect). The corada transcription pages (da321ad57f7fc3f5.html, 41510aa497941b7d.html) were retrieved first and are not the source of any row.', 0, 'Stated in the session transcript before the search ran: at least one result hosting the PDF on the Access Board or the IDeA Center site, about 80 percent likely.', 'incidental', NULL, NULL, '2026-11-06 04:32', 'session_2026-11-06-pipeline-batch-2', NULL, NULL, NULL, NULL);
50	
51	-- source_scans: 5 insert(s), 0 update(s)
52	INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (10, 'REF-00468', 'catalogue', 12, NULL, 'full', 173, 173, 'bae3334434e4025dbc3e17311e4ecb28626f986f3a0eaceebc180e39a1072da8', 0, 'pre-screen', 'Derived text of all 173 pages (e664fb2f8174f4f8-full-text.txt). NOT read end to end. Read in full: PDF pages 16-17 (sampling), 61-65 (turn findings), 90-101 (implications for turning clearance); located by keyword and read in part: pages 34, 48, 67, 90, 92 (door, force). Zero hits on the whole text for light reflectance, LRV, luminance contrast, headroom, overhead or vertical clearance, colour temperature, reverberation: parameters 7, 8, 10, 11 find no value here. Parameter 9: the report says the clear floor area width informs the minimum clearance for doorways but states no door clear width recommendation; not filed. Parameter 6: p.67 reports maximum grip force of the users (a capacity), not a force a door or control may require; not filed. Parameter 3 and 12: ramps are mentioned only in passing on pages 90-100. Filed: turning and passage widths at turns (parameters 4 and 5). Tables are cell sequences without row labels in the text, so only sentence-form figures are filed. Figures are images and unread.', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:33', 'session_2026-11-06-pipeline-batch-2');
53	INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (11, 'REF-01028', 'catalogue', 12, NULL, 'full', NULL, NULL, 'b9353457a95a925b4b646e2c0263d35bdc1b973964f28645110569d14717047a', 0, 'pre-screen', 'BOE consolidated text of Orden TMA/851/2021 (visible-text extraction of the web page, batch 23). The order governs urbanised PUBLIC SPACE (pedestrian routes, street furniture, public toilet cabins), not building interiors, so building corridor, door and headroom values are not here and the rows carry that setting. Read in full: articles 5, 28, 34, 39 (and the 4 paragraphs after art 39). Keyword screen over the rest (contraste, luminancia, reflectancia, LRV, fuerza, esfuerzo, newton, anchura libre, altura libre, círculo, diámetro): other hits are 2,20 m free height repeated in arts 6, 7, 14 (not refiled), 1,50 m circles at play areas and drinking fountains (arts 8, 27; not refiled), and qualitative contrast. Parameters 4, 5, 6, 9, 11 filed; parameter 8 absent (no LRV), parameter 6 absent for toilet controls. Parameters 3 and 12 (ramps, art 14) are already held from this source. Parameters 7 and 10: no hits. Not read end to end.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
54	INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (12, 'REF-01031', 'catalogue', 12, NULL, 'full', 22, 22, 'e61147623cbd9d61ea5ff3e25e97c24b00a4d8314d9414c49120c87e967adc42', 0, 'pre-screen', 'Derived text of all 22 pages of Annex 1 (batch 23). Read in full: item 6 (entrances, pages 3-4), item 7 (corridors and passages, pages 4-5, including obstacles and clear height), and the accessible-toilet clauses on page 11. Located by keyword and not read in full: the other items (parking, elevators, stairs, bathrooms, rooms, pages 1-2, 6-10, 12-22). Parameters 4, 5, 9, 11 filed. The annex states no force (no newton or kilogram figure for doors) and no luminance or light reflectance contrast value: parameters 6 and 8 find no value, and no absence row was filed because the annex was not read end to end. Parameters 7 and 10: no hits. Elevator door widths (0.8 m, 0.9 m), the 1.5 m by 1.5 m passing zones on access routes and the competition-wheelchair figures (1.2 m door, 1.5 m by 1.5 m turning) are stated and not filed. The 0.9 m access-route-to-door figure of item 1 is the route width of 1.2 m already filed under parameter 3.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
55	INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (13, 'REF-01032', 'catalogue', 12, NULL, 'partial', 5, 20, 'de24554e5ad496f16ff1c0f94a1f6ec0b477b3f9948626dac38d0ed054e06933', 0, 'pre-screen', 'Derived text of 5 of the 20 pages of the Diario da Republica issue (pages 1, 2, 9, 10, 20; batch 23). Pages 9 and 10 read in full: sections 2.2 (atria), 2.3 (landings, galleries, corridors), 2.5 (ramps), 2.6 (lifts). Filed: parameters 9 (2.2.3) and 4 (2.3.1, 2.3.2). Parameter 5: 2.2.1, 2.2.2 and 2.3.3 require a manoeuvre zone for a 360-degree rotation, but the dimension sits in section 4.4, which these pages do not hold, so no turning figure is filed. Parameters 6, 7, 8, 10, 11: not on the pages held; NOT examined, because most of the decree is not in the text. The remaining 15 pages are unread.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
56	INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (14, 'REF-01031', 'catalogue', 12, NULL, 'full', 22, 22, 'e61147623cbd9d61ea5ff3e25e97c24b00a4d8314d9414c49120c87e967adc42', 0, 'pre-screen', 'Second reading, same day; replaces the first scan note of this source where they differ. CORRECTION: the first note ended with a sentence about a 0.9 m access-route figure of item 1 being filed under parameter 3. That sentence is wrong and is withdrawn: item 1 states the access-route clear width as 1.2 m, and nothing from item 1 is filed under parameter 3. The 1.2 m access-route width is now filed under parameter 4 (item 1(a)(1)). Everything else in the first note stands.', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2', '2026-11-06 04:35', 'session_2026-11-06-pipeline-batch-2');
